// Security Drift Check - baseline checks over ALL workflows of this instance.
// Input: one item per workflow (from the n8n node). Config comes from the 'Set Configuration Values' node.
// Every finding has a stable key. To silence a finding on purpose, add its key to
// 'acceptedKeys' in the 'Set Configuration Values' node (comma separated). That makes it a named decision.
const cfg = $('Set Configuration Values').first().json;
const ACCEPTED = new Set(String(cfg.acceptedKeys || '').split(',').map(s => s.trim()).filter(Boolean));
let TEST_RE;
try { TEST_RE = new RegExp(cfg.testNamePattern || '_TEST_|TEMP_|_Sandbox', 'i'); } catch (e) { TEST_RE = /_TEST_|TEMP_|_Sandbox/i; }
// Archived workflows are skipped: they cannot run and are not cloned anymore.
const all = $input.all().map(i => i.json).filter(w => w && w.id && !w.isArchived);
const findings = [];
const add = (key, wf, type, hint) => { if (!ACCEPTED.has(key)) findings.push({ key, wfId: wf.id, wfName: wf.name, type, hint: hint || '' }); };

const SECRET_RES = [
  ['PrivateKey', '-----BEGIN [A-Z ]*PRIVATE KEY-----'],
  ['GoogleApiKey', 'AIza[0-9A-Za-z_-]{35}'],
  ['OpenAIKey', 'sk-[A-Za-z0-9]{20,}'],
  ['SlackToken', 'xox[baprs]-[0-9A-Za-z-]{10,}'],
  ['GitHubPAT', 'ghp_[0-9A-Za-z]{36}'],
  ['AwsAccessKey', 'AKIA[0-9A-Z]{16}'],
  ['TelegramBotToken', '[0-9]{8,10}:[A-Za-z0-9_-]{35}'],
  ['BearerToken', 'Bearer [A-Za-z0-9._-]{20,}']
].map(p => [p[0], new RegExp(p[1], 'g')]);
const PLACEHOLDER_RE = /PLACEHOLDER/i;
const TOKEN_HINT_RE = /token|secret|x-api-key|authorization|signature|hmac/i;
const TRIGGER_RE = /(trigger$|\.webhook$)/i;
const blob = (x) => { try { return JSON.stringify(x || {}); } catch (e) { return ''; } };

// Map: which workflows are error handlers (start with an Error Trigger)?
const isHandler = new Map();
for (const wf of all) isHandler.set(wf.id, (wf.nodes || []).some(n => n.type === 'n8n-nodes-base.errorTrigger'));

// "Strictest value ever seen" memory for settings that protect data.
// It is never downgraded automatically: once a workflow was seen with
// saveData*=none or availableInMCP=false, that stays the target.
const sd = $getWorkflowStaticData('global');
const saveTargetOld = sd.saveDataTarget || {};
const mcpTargetOld = sd.mcpTargetFalse || {};
const saveDataTarget = {};
const mcpTargetFalse = {};

for (const wf of all) {
  const nodes = (wf.nodes || []).filter(n => n.type !== 'n8n-nodes-base.stickyNote');
  const st = wf.settings || {};

  // --- 1. Hardcoded secrets: ALL workflows, also inactive ones (templates get cloned) ---
  for (const n of nodes) {
    const s = blob(n.parameters);
    for (const [label, re] of SECRET_RES) {
      const hits = (s.match(re) || []).filter(x => !PLACEHOLDER_RE.test(x));
      if (hits.length) add(wf.id + '::secret::' + n.name + '::' + label, wf, 'Hardcoded secret (' + label + ')',
        'Node: ' + n.name + ' - move it to a credential' + (wf.active ? '' : ' (workflow inactive, still exposed when cloned or exported)'));
    }
  }

  // --- 2. Orphaned parameters.parameters: ALL workflows. n8n ignores it silently ---
  for (const n of nodes) {
    const p = n.parameters;
    if (!p || typeof p !== 'object' || !Object.prototype.hasOwnProperty.call(p, 'parameters')) continue;
    const inner = p.parameters;
    if (!inner || typeof inner !== 'object') continue;
    const fields = Array.isArray(inner) ? '(array, ' + inner.length + ' entries)' : (Object.keys(inner).join(', ') || '(empty)');
    add(wf.id + '::orphan_params::' + n.name, wf, 'Nested parameters.parameters (ignored by n8n)', 'Node: ' + n.name + ' | no effect: ' + fields);
  }

  // --- Protection targets are tracked over ALL workflows, reported only for active ones ---
  const isS = st.saveDataSuccessExecution === 'none';
  const isE = st.saveDataErrorExecution === 'none';
  const old = saveTargetOld[wf.id] || '';
  const targetS = old.indexOf('s') !== -1 || isS;
  const targetE = old.indexOf('e') !== -1 || isE;
  if (targetS || targetE) saveDataTarget[wf.id] = (targetS ? 's' : '') + (targetE ? 'e' : '');
  const mcpFalse = st.availableInMCP === false;
  const mcpTarget = mcpTargetOld[wf.id] === true || mcpFalse;
  if (mcpTarget) mcpTargetFalse[wf.id] = true;

  if (!wf.active) continue;

  // --- 3. Webhook without authentication ---
  if (nodes.some(n => n.type === 'n8n-nodes-base.webhook' && !n.disabled && (!n.parameters || !n.parameters.authentication || n.parameters.authentication === 'none'))) {
    const tok = nodes.some(n => n.type === 'n8n-nodes-base.code' && TOKEN_HINT_RE.test((n.parameters && n.parameters.jsCode) || ''));
    add(wf.id + '::unauth_webhook', wf, 'Webhook without node-level authentication',
      tok ? 'A token check in a Code node may exist - verify, then accept the key' : 'No token check found - add Header Auth or similar');
  }

  // --- 4. Active test / temp workflow ---
  if (TEST_RE.test(wf.name || '')) add(wf.id + '::active_test', wf, 'Active test or temp workflow', 'Name matches ' + TEST_RE);

  // --- 5. Error workflow: missing, self-reference, unknown target, target without Error Trigger ---
  const target = st.errorWorkflow || null;
  if (!target) {
    if (!isHandler.get(wf.id)) add(wf.id + '::no_error_wf', wf, 'No error workflow set', 'Failures of this workflow go unnoticed');
  } else if (target === wf.id) {
    add(wf.id + '::errwf_self', wf, 'Error workflow points to itself', 'Circular reference');
  } else if (!isHandler.has(target)) {
    add(wf.id + '::errwf_unknown', wf, 'Error workflow target not found', 'Target ' + target + ' is not in this instance (deleted or archived?)');
  } else if (isHandler.get(target) === false) {
    add(wf.id + '::errwf_no_trigger', wf, 'Error workflow target has no Error Trigger', 'Target ' + target + ' cannot receive the error call - the alert is lost');
  }

  // --- 6. Execution data protection lowered (drift against strictest value seen) ---
  if (targetS && !isS) add(wf.id + '::savedata_success_lowered', wf, 'Execution data protection lowered (success)',
    'saveDataSuccessExecution=' + (st.saveDataSuccessExecution === undefined ? 'missing (instance default)' : st.saveDataSuccessExecution) + ', was "none" before');
  if (targetE && !isE) add(wf.id + '::savedata_error_lowered', wf, 'Execution data protection lowered (error)',
    'saveDataErrorExecution=' + (st.saveDataErrorExecution === undefined ? 'missing (instance default)' : st.saveDataErrorExecution) + ', was "none" before');

  // --- 7. MCP exposure re-enabled (drift against strictest value seen) ---
  if (mcpTarget && !mcpFalse) add(wf.id + '::mcp_exposed', wf, 'MCP access re-enabled', 'availableInMCP was false before and is now ' + (st.availableInMCP === undefined ? 'missing (instance default)' : st.availableInMCP));

  // --- 8. Received webhook auth header stored in the execution log ---
  const succ = st.saveDataSuccessExecution;
  const liveEqualsDraft = !!wf.versionId && wf.versionId === wf.activeVersionId;
  for (const n of nodes) {
    if (n.type === 'n8n-nodes-base.webhook' && n.parameters && n.parameters.authentication === 'headerAuth' && succ !== 'none') {
      if (n.disabled === true && liveEqualsDraft) continue;
      add(wf.id + '::webhook_header_log::' + n.name, wf, 'Webhook auth header stored in execution log',
        'Trigger: ' + n.name + ' - the received auth header is saved with successful runs. Set saveDataSuccessExecution to "none"');
    }
  }

  // --- 9. Dead branches: edge to missing node, unreachable node, disabled node in the path ---
  const names = new Set(nodes.map(n => n.name));
  const conns = wf.connections || {};
  for (const src of Object.keys(conns)) {
    for (const br of ((conns[src] && conns[src].main) || [])) for (const v of (br || [])) {
      if (v && v.node && !names.has(v.node)) add(wf.id + '::dead_edge::' + src + '::' + v.node, wf, 'Connection to a missing node', src + ' -> ' + v.node);
    }
  }
  const start = nodes.filter(n => TRIGGER_RE.test(n.type || '')).map(n => n.name);
  if (start.length) {
    const seen = new Set(start); const stack = start.slice();
    while (stack.length) {
      const cur = stack.pop();
      for (const br of ((conns[cur] && conns[cur].main) || [])) for (const v of (br || [])) {
        if (v && v.node && names.has(v.node) && !seen.has(v.node)) { seen.add(v.node); stack.push(v.node); }
      }
    }
    for (const n of nodes) {
      if (seen.has(n.name) || TRIGGER_RE.test(n.type || '')) continue;
      // Sub-nodes (models, tools, memory) hang off ai_* connections, not main - skip them
      if (Object.keys(conns[n.name] || {}).some(k => k.indexOf('ai_') === 0)) continue;
      add(wf.id + '::unreachable::' + n.name, wf, 'Node not reachable from any trigger', n.name + ' never runs');
    }
  }
  for (const n of nodes) {
    if (!n.disabled || TRIGGER_RE.test(n.type || '')) continue;
    const hasNext = ((conns[n.name] && conns[n.name].main) || []).some(br => (br || []).length > 0);
    if (hasNext) add(wf.id + '::disabled_in_path::' + n.name, wf, 'Disabled node in the main path', n.name + ' is passed through, its step does not happen');
  }
}

return [{ json: {
  findings, count: findings.length,
  scannedTotal: all.length, scannedActive: all.filter(w => w.active).length,
  acceptedCount: ACCEPTED.size, saveDataTarget, mcpTargetFalse,
  ts: new Date().toISOString()
} }];

// Alerts only on NEW finding keys (diff against the last successful run).
// This node only READS the baseline. It is written in 'Store Baseline Data',
// i.e. AFTER the email went out. If sending fails, the run stops there and
// the same findings are reported again next time - nothing gets lost.
const data = $input.first().json;
const current = data.findings || [];
const currentKeys = current.map(f => f.key);
const sd = $getWorkflowStaticData('global');
const lastKeys = sd.lastFindingKeys || [];
const lastSet = new Set(lastKeys);
const curSet = new Set(currentKeys);
const newFindings = current.filter(f => !lastSet.has(f.key));
const resolvedCount = lastKeys.filter(k => !curSet.has(k)).length;

const esc = (t) => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const rows = newFindings.map(f => '<tr><td>' + esc(f.wfName) + '<br><small>' + esc(f.wfId) + '</small></td><td>' + esc(f.type) + '</td><td>' + esc(f.hint) + '</td><td><code>' + esc(f.key) + '</code></td></tr>').join('');
const subject = '[n8n] Security drift: ' + newFindings.length + ' new finding(s)';
const html = '<p><b>' + newFindings.length + ' new finding(s)</b> (' + data.count + ' open in total, '
  + resolvedCount + ' resolved since last run, ' + data.scannedActive + ' active of ' + data.scannedTotal + ' workflows scanned).</p>'
  + '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">'
  + '<tr><th>Workflow</th><th>Finding</th><th>Hint</th><th>Key (to accept)</th></tr>' + rows + '</table>'
  + '<p style="font-size:12px;color:#666">To accept a finding on purpose, add its key to acceptedKeys in the Set Configuration Values node.</p>';

return [{ json: { ...data, currentKeys, newFindings, newCount: newFindings.length, resolvedCount, hasNew: newFindings.length > 0, subject, html } }];

// Writes the baseline. Deliberately the LAST node of the run.
// Reached via: 'Check for New Findings' = false, or after the email was sent.
// If the email fails, the run stops before this node and nothing is lost.
// NOTE: n8n persists static data only in production runs (schedule).
// Manual test runs show the right diff but do not save the baseline.
const data = $('Identify New Findings').first().json || {};
const sd = $getWorkflowStaticData('global');
const before = (sd.lastFindingKeys || []).length;
// Empty-map guard: replace a protection map only if the check node really
// delivered one. A missing field must never wipe the stored targets.
const isMap = (m) => !!m && typeof m === 'object' && !Array.isArray(m);
if (isMap(data.saveDataTarget)) sd.saveDataTarget = data.saveDataTarget;
if (isMap(data.mcpTargetFalse)) sd.mcpTargetFalse = data.mcpTargetFalse;
sd.lastFindingKeys = Array.isArray(data.currentKeys) ? data.currentKeys : [];
sd.lastRun = data.ts;
return [{ json: { baselineKeys: sd.lastFindingKeys.length, baselineKeysBefore: before, newCount: data.newCount, resolvedCount: data.resolvedCount, lastRun: sd.lastRun } }];
